SELECT COALESCE(SUM(points), 0)
FROM tj_learning.points_record
WHERE user_id = #{userId}
AND type = #{type}
AND create_time BETWEEN #{begin} AND #{end}

SELECT SUM(points) AS points,type
FROM tj_learning.points_record
WHERE user_id = #{userId}
AND create_time BETWEEN #{begin} AND #{end}
GROUP BY type
order by points
